if(session_status()===PHP_SESSION_NONE)session_start();
require_once __DIR__.'/config/conexao.php'; require_once __DIR__.'/auth/verifica_login.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$fornecedores=$pdo->query("SELECT id,COALESCE(NULLIF(nome_fantasia,''),razao_social) nome FROM fornecedores WHERE status='ATIVO' ORDER BY nome")->fetchAll();
$produtos=$pdo->query("SELECT p.id,p.codigo,p.sku,p.nome,'Produto para Venda' tipo,COALESCE(NULLIF(f.nome_fantasia,''),f.razao_social) fornecedor FROM produtos p LEFT JOIN fornecedores f ON f.id=p.fornecedor_id WHERE p.status='ATIVO' ORDER BY p.nome LIMIT 50")->fetchAll();
$suprimentos=$pdo->query("SELECT s.id,s.codigo,s.nome,'Material de Uso' tipo,COALESCE(NULLIF(f.nome_fantasia,''),f.razao_social) fornecedor FROM suprimentos s LEFT JOIN fornecedor_suprimentos fs ON fs.suprimento_id=s.id AND fs.fornecedor_preferencial=1 LEFT JOIN fornecedores f ON f.id=fs.fornecedor_id WHERE s.status='ATIVO' ORDER BY s.nome LIMIT 50")->fetchAll();
$msg=$_SESSION['itens_msg']??'';$tipo=$_SESSION['itens_tipo']??'sucesso';unset($_SESSION['itens_msg'],$_SESSION['itens_tipo']);
require_once __DIR__.'/includes/header.php'; require_once __DIR__.'/includes/sidebar.php';
?>
