<script>document.addEventListener('DOMContentLoaded',function(){const t=document.getElementById('tipo_item'),p=document.getElementById('produto-campos'),m=document.getElementById('material-campos');function a(){const produto=t.value==='PRODUTO';p.style.display=produto?'block':'none';m.style.display=produto||!t.value?'none':'block';p.querySelectorAll('input').forEach(x=>x.disabled=!produto);m.querySelectorAll('input').forEach(x=>x.disabled=produto||!t.value);}t.addEventListener('change',a);a();});</script>
